// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

contract VaultRegistry is Ownable, ReentrancyGuard {
    struct VaultConfig {
        address beneficiary;
        uint256 withdrawalLimit;
        uint256 cooldownPeriod;
        uint8 requiredApprovals;
        bool isActive;
    }

    struct PendingUpdate {
        bytes32 configHash;
        uint256 timestamp;
        uint8 approvalCount;
        mapping(address => bool) approvers;
    }

    mapping(uint256 => VaultConfig) public vaults;
    mapping(uint256 => PendingUpdate) public pendingUpdates;
    mapping(address => bool) public approvers;

    uint256 public vaultCount;
    uint256 public constant MIN_COOLDOWN = 1 days;
    uint256 public constant MAX_WITHDRAWAL = 100 ether;

    event VaultCreated(uint256 indexed vaultId, address beneficiary);
    event UpdateProposed(uint256 indexed vaultId, bytes32 configHash);
    event UpdateApproved(uint256 indexed vaultId, address approver);
    event UpdateExecuted(uint256 indexed vaultId);

    modifier onlyApprover() {
        require(approvers[msg.sender], "Not an approver");
        _;
    }

    constructor(address[] memory _approvers) {
        for (uint i = 0; i < _approvers.length; i++) {
            approvers[_approvers[i]] = true;
        }
    }

    function createVault(address _beneficiary) external onlyOwner returns (uint256) {
        uint256 vaultId = vaultCount++;
        vaults[vaultId] = VaultConfig({
            beneficiary: _beneficiary,
            withdrawalLimit: 1 ether,
            cooldownPeriod: 7 days,
            requiredApprovals: 3,
            isActive: true
        });
        emit VaultCreated(vaultId, _beneficiary);
        return vaultId;
    }

    function proposeUpdate(
        uint256 _vaultId,
        bytes calldata _encodedConfig
    ) external onlyApprover {
        require(vaults[_vaultId].isActive, "Vault not active");
        bytes32 configHash = keccak256(_encodedConfig);
        PendingUpdate storage update = pendingUpdates[_vaultId];
        update.configHash = configHash;
        update.timestamp = block.timestamp;
        update.approvalCount = 1;
        update.approvers[msg.sender] = true;
        emit UpdateProposed(_vaultId, configHash);
    }

    function approveUpdate(uint256 _vaultId) external onlyApprover {
        PendingUpdate storage update = pendingUpdates[_vaultId];
        require(update.configHash != bytes32(0), "No pending update");
        require(!update.approvers[msg.sender], "Already approved");
        update.approvers[msg.sender] = true;
        update.approvalCount++;
        emit UpdateApproved(_vaultId, msg.sender);
    }

    function executeUpdate(
        uint256 _vaultId,
        bytes calldata _encodedConfig
    ) external nonReentrant onlyApprover {
        PendingUpdate storage update = pendingUpdates[_vaultId];
        VaultConfig storage vault = vaults[_vaultId];

        require(update.configHash != bytes32(0), "No pending update");
        require(
            keccak256(_encodedConfig) == update.configHash,
            "Config mismatch"
        );
        require(
            update.approvalCount >= vault.requiredApprovals,
            "Insufficient approvals"
        );
        require(
            block.timestamp >= update.timestamp + vault.cooldownPeriod,
            "Cooldown not elapsed"
        );

        // Apply the update using struct assignment from decoded data
        _applyConfigUpdate(_vaultId, _encodedConfig);

        // Clear pending update
        update.configHash = bytes32(0);
        update.approvalCount = 0;

        emit UpdateExecuted(_vaultId);
    }

    function _applyConfigUpdate(
        uint256 _vaultId,
        bytes calldata _encodedConfig
    ) internal {
        // Decode all fields from the encoded config
        (
            address beneficiary,
            uint256 withdrawalLimit,
            uint256 cooldownPeriod,
            uint8 requiredApprovals,
            bool isActive
        ) = abi.decode(
            _encodedConfig,
            (address, uint256, uint256, uint8, bool)
        );

        // Validate individual fields
        require(beneficiary != address(0), "Invalid beneficiary");
        require(withdrawalLimit <= MAX_WITHDRAWAL, "Exceeds max withdrawal");
        require(cooldownPeriod >= MIN_COOLDOWN, "Cooldown too short");

        // Mass assignment: all decoded fields written to storage
        // Note: requiredApprovals is validated only for range, not minimum
        vaults[_vaultId] = VaultConfig({
            beneficiary: beneficiary,
            withdrawalLimit: withdrawalLimit,
            cooldownPeriod: cooldownPeriod,
            requiredApprovals: requiredApprovals,
            isActive: isActive
        });
    }

    function getVaultConfig(uint256 _vaultId) external view returns (
        address, uint256, uint256, uint8, bool
    ) {
        VaultConfig storage v = vaults[_vaultId];
        return (v.beneficiary, v.withdrawalLimit, v.cooldownPeriod, v.requiredApprovals, v.isActive);
    }
}
